def reading(scan,line,rd,alt,ev,wt='high'):
    a.reads.append(dict(cote=91,scan=scan,line=line,reading=rd,alternative=alt,evidence=ev,weight=wt,confidence='Visual reading unresolved: no scan image supplied. Mathematical support is stated separately.'))
def link(kind,fr,to,what,ev,ids):
    a.links.append(dict(kind=kind,**{'from':fr},to=to,what=what,evidence=ev,note_ids=ids))
